import { getVercelOidcToken } from '@vercel/oidc';
import { isDetachedInteractiveAuth, validateCallbackUrl, validateWebhookUrl, } from './internal/url-validation.js';
export async function startAuthorization(connector, params, options) {
    if (!connector) {
        throw new Error('connector is required');
    }
    const detachedInteractiveAuth = isDetachedInteractiveAuth();
    if (!detachedInteractiveAuth && options?.callbackUrl !== undefined) {
        validateCallbackUrl(options.callbackUrl);
    }
    if (options?.webhook !== undefined) {
        validateWebhookUrl(options.webhook);
    }
    const vercelToken = options?.vercelToken ?? (await getVercelOidcToken());
    const endpoint = `https://api.vercel.com/v1/connect/authorize/${encodeURIComponent(connector)}`;
    const deviceCode = options?.deviceCode ?? (detachedInteractiveAuth ? true : undefined);
    const returnUrl = !detachedInteractiveAuth && options?.callbackUrl !== undefined
        ? { returnUrl: options.callbackUrl }
        : {};
    const body = {
        ...params,
        ...returnUrl,
        ...(options?.webhook !== undefined && { webhook: options.webhook }),
        ...(deviceCode !== undefined && {
            deviceCode,
        }),
        ...(options?.expiresInMs !== undefined && {
            expiresInMs: options.expiresInMs,
        }),
    };
    const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            Authorization: `Bearer ${vercelToken}`,
        },
        body: JSON.stringify(body),
    });
    if (!response.ok) {
        let errorText;
        try {
            errorText = await response.text();
        }
        catch { }
        throw new Error(`Failed to start authorization: ${response.status} ${response.statusText}${errorText ? ` - ${errorText}` : ''}`);
    }
    const data = await response.json();
    return data;
}
